  }
}
\begin{mytext67}
Definition is_fixpoint (f: Z -> Z) (x: Z): Prop :=
  f x = x.

\end{mytext67}

\newtcblisting{mytext68}{
  boxrule=0pt,
  arc=0pt,
  outer arc=0pt,
  top=0pt,
  bottom=0pt,
  listing only,
  left=15.5pt,
