  arc=0pt,
  outer arc=0pt,
  top=0pt,
  bottom=0pt,
  listing only,
  left=15.5pt,
  enhanced,
  listing options={
    style=COQ,
    showstringspaces=false,
    mathescape=true,
  },
  overlay={
  }
}
\begin{mytext12}
Example quad_ex2: forall x: Z,
  x * x + 3 * x + 4 > 0.
Proof.
(* 请在此处填入你的证明，以_[Qed]_结束。 *)

\end{mytext12}
