Theorem comp_assoc: forall (A B C D: Type) (f: C -> D) (g: B -> C) (h: A -> B),
  comp f (comp g h) = comp (comp f g) h.
Proof.
  intros.
  unfold comp.
  reflexivity.
Qed.

\end{mytext78}
